import React from 'react';
import { MapContainer, TileLayer, CircleMarker, Popup } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';

function MapView({ crimes }) {
  const getColor = (type) => {
    switch(type) {
      case 'Theft': return 'red';
      case 'Assault': return 'orange';
      case 'Burglary': return 'blue';
      default: return 'green';
    }
  }

  const center = crimes.length ? [crimes[0].Latitude, crimes[0].Longitude] : [20.5937, 78.9629];

  return (
    <MapContainer center={center} zoom={5} style={{ height: '100%', width: '100%' }}>
      <TileLayer
        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        attribution="&copy; OpenStreetMap contributors"
      />

      {crimes.map((crime, idx) => (
        <CircleMarker
          key={idx}
          center={[crime.Latitude, crime.Longitude]}
          pathOptions={{ color: getColor(crime.CrimeCode || crime.Type) }}
          radius={6}
        >
          <Popup>
            <strong>{crime.CrimeCode || crime.Type}</strong><br />
            {crime.District}, {crime.Neighborhood}<br />
            {crime.CrimeDateTime}
          </Popup>
        </CircleMarker>
      ))}
    </MapContainer>
  );
}

export default MapView;
